{"path": "/tmp/probe.py", "content": "import http.client, json, sys

HOST, PORT = "frogwaf", 1337

def post(body_bytes, ctype="application/json", path="/addContact", extra=None):
    c = http.client.HTTPConnection(HOST, PORT, timeout=15)
    h = {"Content-Type": ctype}
    if extra: h.update(extra)
    c.request("POST", path, body=body_bytes, headers=h)
    r = c.getresponse()
    data = r.read().decode("utf-8", "replace")
    c.close()
    return r.status, data

def country(val):
    return json.dumps({"firstName":"Adam","lastName":"Smith","description":"Hello","country":val}).encode()

def summarize(st, data):
    if "Frog-WAF" in data:
        i = data.find("Malicious input found")
        return "WAF:" + data[i:i+120].replace("\n"," ")
    return f"APP({st}):{data[:100]}"

tests = []
# single chars and pairs
chars = ['#','*','$','{','}','(',')',';','|','&','<','>','\'','"','/','\\','`','%','+','-','_','.','@','!','?',':','=',',','[',']','~','^']
for ch in chars:
    tests.append("a"+ch+"b")
pats = ["..", "../", "..\\", "${", "}#", "#{", "*/", "/*", "--", "//", "0x", "or 1=1", "OR 1=1", "sleep(1)", "waitfor", "exec", "cmd", "sh ", "cat ", "union select", "<script>", "onerror=", "javascript:", "document.cookie", "java.lang", "Runtime", "T(", "class", "%27", "%23", "\\u0023", "\\u002a", "\\x23", "\\0"]
for p in pats:
    tests.append(p)

for t in tests:
    st, data = post(country(t))
    print(repr(t), "->", summarize(st, data))
"}

