{"content": "import http.client, json, socket

HOST, PORT = "frogwaf", 1337

def post(body, ctype="application/json", timeout=40):
    if isinstance(body,str): body = body.encode()
    c = http.client.HTTPConnection(HOST, PORT, timeout=timeout)
    try:
        c.request("POST", "/addContact", body=body, headers={"Content-Type": ctype})
        r = c.getresponse(); data = r.read().decode("utf-8","replace")
        return r.status, data
    finally:
        c.close()

def summ(st, data):
    if "Frog-WAF" in data:
        i = data.find("Malicious input found")
        return "WAF " + data[i+24:i+110].strip()
    return f"APP({st}) {data[:120]}"

def show(name, body, ctype="application/json"):
    try:
        st, data = post(body, ctype)
        print(f"{name} [{len(body) if not isinstance(body,str) else len(body)}B]: {summ(st,data)}")
    except Exception as e:
        print(f"{name}: EXC {e}")

MAL = 'a#b'
print("== padding field BEFORE country (WAF read/size limits) ==")
for n in (100, 1000, 4000, 8000, 16000, 64000, 1000000, 3000000):
    body = '{"pad":"' + "A"*n + '","firstName":"Adam","lastName":"Smith","description":"Hello","country":"' + MAL + '"}'
    show(f"pad-before {n}", body)

print("== big/deep pad constructs in unknown field, malicious country after ==")
def deep(n):
    return "["*n + "]"*n
for n in (100, 500, 900, 1000, 1200, 2000, 10000):
    body = '{"pad":' + deep(n) + ',"firstName":"Adam","lastName":"Smith","description":"Hello","country":"' + MAL + '"}'
    show(f"deep {n}", body)

print("== big numbers ==")
for n in (100, 500, 1000, 2000, 10000):
    body = '{"pad":' + "1"*n + ',"firstName":"Adam","lastName":"Smith","description":"Hello","country":"' + MAL + '"}'
    show(f"bignum {n}", body)

print("== lone surrogate / odd strings ==")
for pad in ['\\ud800', '\\udfff', '\\ud800\\ud800', '\\u0000', '\\uFFFF', '\\uD83D', '\\uDE00']:
    body = '{"pad":"' + pad + '","firstName":"Adam","lastName":"Smith","description":"Hello","country":"' + MAL + '"}'
    show(f"pad {pad}", body)

print("== many duplicate keys ==")
body = '{"pad":"x",' + ",".join(['"k":"v"']*5000) + ',"firstName":"Adam","lastName":"Smith","description":"Hello","country":"' + MAL + '"}'
show("5000 dup-ish keys", body)

print("== malformed-but-jackson-ok? trailing structures ==")
for suffix in ['', 'null', '[]', '{}', '"x"', '1', '\n\n', '   ']:
    body = '{"firstName":"Adam","lastName":"Smith","description":"Hello","country":"' + MAL + '"}' + suffix
    show(f"trailing {suffix!r}", body)
