{"content": "import http.client, re, json

HOST, PORT = "frogwaf", 1337

def post(d, label):
    body = json.dumps(d).encode()
    c = http.client.HTTPConnection(HOST, PORT, timeout=10)
    try:
        c.request("POST", "/addContact", body=body, headers={"Content-Type": "application/json", "Content-Length": str(len(body))})
        r = c.getresponse()
        data = r.read().decode("utf-8", "replace")
        m = re.search(r'<h1[^>]*>(.*?)</h1>', data, re.S)
        if m:
            mm = re.search(r'attackType=([^,]+), attackString=([^)]*)\)', m.group(1))
            tag = f"WAF {mm.group(1)}:{mm.group(2)}" if mm else "WAF ?"
        elif '"violations"' in data:
            tag = "APP_VALIDATION"
        else:
            tag = data[:100].replace("\n", " ")
        print(f"{label:38s} {r.status} {tag[:110]}")
    finally:
        c.close()

base = {"firstName": "Adam", "lastName": "Smith", "description": "Hello", "country": "Germany"}
for field in ["firstName", "lastName", "description", "country"]:
    for payload in ["'", ";", "class", "${true}", "<x>", "1", "eval"]:
        d = dict(base)
        d[field] = payload
        post(d, f"{field}={payload!r}")
    print()
